import { useTranslation } from 'react-i18next'
import { clsx } from 'clsx'

const langs = [
  { code: 'en', label: 'English' },
  { code: 'de', label: 'Deutsch' },
  { code: 'es', label: 'Español' },
]

export function LanguagePage() {
  const { i18n } = useTranslation()
  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-2xl mx-auto">
        <h2 className="font-semibold mb-1">Language</h2>
        <p className="text-sm text-muted-foreground mb-6">Choose your preferred language</p>
        <div className="bg-surface rounded-xl border border-border divide-y divide-border">
          {langs.map((l) => (
            <button key={l.code} onClick={() => i18n.changeLanguage(l.code)}
              className={clsx('w-full flex items-center justify-between px-5 py-3 text-sm hover:bg-muted/40 transition-colors',
                i18n.language === l.code && 'text-accent font-medium')}>
              <span>{l.label}</span>
              {i18n.language === l.code && <span className="text-xs">✓ Active</span>}
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}
